16	const (
17		originRemote          = "origin"
18		checkpointTokenEnvVar = "ENTIRE_CHECKPOINT_TOKEN"
19	)
20	
21	const (
22		ProtocolSSH   = "ssh"
23		ProtocolHTTPS = "https"
24	)
25	
26	type Info struct {
27		Protocol string
28		Host     string
29		Owner    string
30		Repo     string
31	}
32	
33	// FetchURL returns the effective checkpoint fetch URL for the current repository.
34	// If strategy_options.checkpoint_remote is configured, the returned URL is derived
35	// from the origin remote's protocol/host and the configured checkpoint repo.
36	// Otherwise, the origin remote URL is returned directly.
37	//
38	// If ENTIRE_CHECKPOINT_TOKEN is set and a checkpoint remote is configured, HTTPS is
39	// forced so the token can be used even when origin is configured via SSH.
40	func FetchURL(ctx context.Context) (string, error) {
41		withToken := strings.TrimSpace(os.Getenv(checkpointTokenEnvVar)) != ""
42	
43		originURL, originErr := GetRemoteURL(ctx, originRemote)
44		if originErr != nil {
45			originURL = ""
46		}
47	
48		if originURL != "" && withToken {
49			if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
50				originURL = tokenURL
51			}
52		}
53	
54		s, err := settings.Load(ctx)
55		if err != nil {
56			if originURL != "" {
57				logFallback(ctx, "fetch", originURL, "load settings", err)
58				return originURL, nil
59			}
60			return "", fmt.Errorf("load settings: %w", err)
61		}
62	
63		config := s.GetCheckpointRemote()
64		if config == nil {
65			if originURL == "" {
66				return "", fmt.Errorf("no fetch URL found: %w", originErr)
67			}
68			return originURL, nil
69		}
70	
71		if withToken {
72			host, ok := providerHost(config.Provider)
73			if ok {
74				checkpointURL, err := deriveCheckpointURLFromInfo(&Info{
75					Protocol: ProtocolHTTPS,
76					Host:     host,
77				}, config)
78				if err == nil {
79					return checkpointURL, nil
80				}
81			}
82	
83			// In token-based execution path, short-circuit to avoid additional
84			// change in protocol.
85			if originURL != "" {
86				return originURL, nil
87			}
88		}
89	
90		if originURL == "" {
91			return "", fmt.Errorf("no fetch URL found: %w", originErr)
92		}
93	
94		info, err := ParseURL(originURL)
95		if err != nil {
96			logFallback(ctx, "fetch", originURL, "parse origin remote URL", err)
97			return originURL, nil
98		}
99	
100		checkpointURL, err := deriveCheckpointURLFromInfo(info, config)
101		if err != nil {
102			logFallback(ctx, "fetch", originURL, "derive checkpoint remote URL", err)
103			return originURL, nil
104		}
105	
106		return checkpointURL, nil
107	}
108	
109	// PushURL returns the effective checkpoint push URL for the current repository.
110	// Unlike FetchURL:
111	//   - it derives protocol from the requested push remote, not always origin
112	//   - it skips checkpoint remote use when the push remote owner differs
113	//     from the configured checkpoint remote owner
114	//
115	// If ENTIRE_CHECKPOINT_TOKEN is set, HTTPS is forced so the token can be used
116	// even when the push remote is configured via SSH.
117	//
118	// The boolean return value reports whether a dedicated checkpoint_remote is
119	// configured and should be used for push. When false, the returned URL is the
120	// repository's origin URL as a fallback.
121	func PushURL(ctx context.Context, pushRemoteName string) (string, bool, error) {
122		originURL := ""
123		if resolvedOriginURL, err := GetRemoteURL(ctx, originRemote); err == nil {
124			originURL = resolvedOriginURL
125		}
126	
127		s, err := settings.Load(ctx)
128		if err != nil {
129			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
130			if fallbackErr == nil {
131				logFallback(ctx, "push", fallbackURL, "load settings", err,
132					slog.String("push_remote", pushRemoteName),
133				)
134				return fallbackURL, false, nil
135			}
136			return "", false, fmt.Errorf("load settings: %w", err)
137		}
138	
139		config := s.GetCheckpointRemote()
140		if config == nil {
141			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
142			if fallbackErr != nil {
143				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
144			}
145			return fallbackURL, false, nil
146		}
147	
148		pushRemoteURL, err := GetRemoteURL(ctx, pushRemoteName)
149		if err != nil {
150			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
151			if fallbackErr == nil {
152				logFallback(ctx, "push", fallbackURL, "get push remote URL", err,
153					slog.String("push_remote", pushRemoteName),
154				)
155				return fallbackURL, false, nil
156			}
157			return "", true, fmt.Errorf("no push URL found: %w", err)
158		}
159	
160		pushInfo, err := ParseURL(pushRemoteURL)
161		if err != nil {
162			if originURL != "" {
163				logFallback(ctx, "push", originURL, "parse push remote URL", err,
164					slog.String("push_remote", pushRemoteName),
165				)
166				return originURL, false, nil
167			}
168			return "", true, fmt.Errorf("no push URL found: %w", err)
169		}
170		if strings.TrimSpace(os.Getenv(checkpointTokenEnvVar)) != "" {
171			pushInfo = &Info{
172				Protocol: ProtocolHTTPS,
173				Host:     pushInfo.Host,
174				Owner:    pushInfo.Owner,
175				Repo:     pushInfo.Repo,
176			}
177		}
178	
179		checkpointOwner := config.Owner()
180		if pushInfo.Owner != "" && checkpointOwner != "" && !strings.EqualFold(pushInfo.Owner, checkpointOwner) {
181			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
182			if fallbackErr != nil {
183				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
184			}
185			return fallbackURL, false, nil
186		}
187	
188		pushURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
189		if err != nil {
190			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
191			if fallbackErr == nil {
192				logFallback(ctx, "push", fallbackURL, "derive push checkpoint URL", err,
193					slog.String("push_remote", pushRemoteName),
194				)
195				return fallbackURL, false, nil
196			}
197			return "", true, fmt.Errorf("no push URL found: %w", err)
198		}
199	
200		return pushURL, true, nil
201	}
202	
203	// Configured reports whether a structured checkpoint_remote is configured.
204	func Configured(ctx context.Context) bool {
205		s, err := settings.Load(ctx)
206		if err != nil {
207			logging.Warn(ctx, "checkpoint remote configuration unavailable; treating as not configured",
208				slog.String("error", err.Error()),
209			)
210			return false
211		}
212		return s.GetCheckpointRemote() != nil
213	}
214	
215	func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
216		cmd := exec.CommandContext(ctx, "git", "remote", "get-url", remoteName)
217		output, err := cmd.Output()
218		if err != nil {
219			return "", fmt.Errorf("remote %q not found", remoteName)
220		}
221		return strings.TrimSpace(string(output)), nil
222	}
223	
224	func ParseURL(rawURL string) (*Info, error) {
225		rawURL = strings.TrimSpace(rawURL)
226	
227		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
228			parts := strings.SplitN(rawURL, ":", 2)
229			if len(parts) != 2 {
230				return nil, fmt.Errorf("invalid SSH URL: %s", RedactURL(rawURL))
231			}
232	
233			hostPart := parts[0]
234			host := hostPart
235			if idx := strings.Index(hostPart, "@"); idx >= 0 {
236				host = hostPart[idx+1:]
237			}
238	
239			pathPart := strings.TrimSuffix(parts[1], ".git")
240			owner, repo, err := splitOwnerRepo(pathPart)
241			if err != nil {
242				return nil, err
243			}
244	
245			return &Info{Protocol: ProtocolSSH, Host: host, Owner: owner, Repo: repo}, nil
246		}
247	
248		u, err := url.Parse(rawURL)
249		if err != nil {
250			return nil, fmt.Errorf("invalid URL: %s", RedactURL(rawURL))
251		}
252		if u.Scheme == "" {
253			return nil, fmt.Errorf("no protocol in URL: %s", RedactURL(rawURL))
254		}
255	
256		pathPart := strings.TrimPrefix(u.Path, "/")
257		owner, repo, err := splitOwnerRepo(pathPart)
258		if err != nil {
259			return nil, err
260		}
261	
262		return &Info{Protocol: u.Scheme, Host: u.Hostname(), Owner: owner, Repo: repo}, nil
263	}
264	
265	func DeriveCheckpointURL(pushRemoteURL string, config *settings.CheckpointRemoteConfig) (string, error) {
266		info, err := ParseURL(pushRemoteURL)
267		if err != nil {
268			return "", fmt.Errorf("cannot parse push remote URL: %w", err)
269		}
270		return deriveCheckpointURLFromInfo(info, config)
271	}
272	
273	func ExtractOwnerFromRemoteURL(rawURL string) string {
274		info, err := ParseURL(rawURL)
275		if err != nil {
276			return ""
277		}
278		return info.Owner
279	}
280	
281	func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
282		switch info.Protocol {
283		case ProtocolSSH:
284			return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
285		case ProtocolHTTPS:
286			return fmt.Sprintf("https://%s/%s.git", info.Host, config.Repo), nil
287		default:
288			return "", fmt.Errorf("unsupported protocol %q in origin remote", info.Protocol)
289		}
290	}
291	
292	func deriveTokenOriginURL(originURL string) (string, bool) {
293		info, err := ParseURL(originURL)
294		if err != nil {
295			return "", false
296		}
297		if info.Host == "" || info.Owner == "" || info.Repo == "" {
298			return "", false
299		}
300		return fmt.Sprintf("https://%s/%s/%s.git", info.Host, info.Owner, info.Repo), true
301	}
302	
303	func providerHost(provider string) (string, bool) {
304		switch strings.ToLower(strings.TrimSpace(provider)) {
305		case "github":
306			return "github.com", true
307		case "gitlab":
308			return "gitlab.com", true
309		default:
310			return "", false
311		}
312	}
313	
314	func splitOwnerRepo(path string) (string, string, error) {
315		path = strings.TrimSuffix(path, ".git")
316		parts := strings.SplitN(path, "/", 2)
317		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
318			return "", "", fmt.Errorf("cannot parse owner/repo from path: %s", path)
319		}
320		return parts[0], parts[1], nil
321	}
322	
323	func RedactURL(rawURL string) string {
324		u, err := url.Parse(rawURL)
325		if err != nil {
326			if idx := strings.Index(rawURL, "@"); idx >= 0 {
327				if colonIdx := strings.Index(rawURL[idx:], ":"); colonIdx >= 0 {
328					return rawURL[idx+1:idx+colonIdx] + ":***"
329				}
330			}
331			return "<unparseable>"
332		}
333		u.User = nil
334		u.RawQuery = ""
335		return u.Scheme + "://" + u.Host + u.Path
336	}
337	
338	func logFallback(ctx context.Context, operation, fallbackURL, reason string, err error, attrs ...any) {
339		logAttrs := []any{
340			slog.String("operation", operation),
341			slog.String("fallback_url", RedactURL(fallbackURL)),
342			slog.String("reason", reason),
343			slog.String("error", err.Error()),
344		}
345		logAttrs = append(logAttrs, attrs...)
346		logging.Warn(ctx, "checkpoint remote URL resolution fell back to alternate remote URL", logAttrs...)
347	}
348	
349	func resolvePushFallbackURL(ctx context.Context, pushRemoteName, originURL string) (string, error) {
350		if originURL != "" {
351			return originURL, nil
352		}
353		if pushRemoteName == "" || pushRemoteName == originRemote {
354			return "", fmt.Errorf("remote %q not found", originRemote)
355		}
356		return GetRemoteURL(ctx, pushRemoteName)
357	}
